"""Opt-in AP editorial layout; content stays in the issue JSON."""
from html import escape as esc
ORIGIN='https://www.apholdings.kr'

def cover(i,email=False):
    h=i['hero']; origin=ORIGIN if email else ''
    source=h['path'] if email else h['poster']
    image=f'<img class="motion-image" src="{origin}{source}" alt="{esc(h["alt"])}" width="600" height="338" style="display:block;width:100%;height:auto"'+('>' if email else f' data-motion-src="{h["path"]}" data-poster-src="{h["poster"]}">')
    if email:return image+f'<p style="font-size:11px;color:#657083">{esc(h["caption"])}</p>'
    return f'<figure class="motion-cover">{image}<figcaption>{esc(h["caption"])}</figcaption><button type="button" hidden data-motion-toggle aria-pressed="false">움직임 정지</button></figure>'

def web(i,b):
    stories=''.join(f'<article class="editorial-story" id="story-{n}"><p class="eyebrow">{n:02d} / {esc(s.get("category","AI NEWS"))}</p><h2>{esc(s["title"])}</h2><p class="source">{esc(s["source"])} · 발표 {esc(s["published"])}</p><p class="editorial-summary">{esc(s["summary"])}</p>{b.figure(s)}<p>{esc(s["fact"])}</p><aside><b>AP의 관점</b><p>{esc(s["insight"])}</p></aside><a class="quiet-link" href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer">공식 원문 읽기 ↗</a></article>' for n,s in enumerate(i['stories'],1))
    body=f'<div class="editorial-v2"><div class="editorial-brand"><span>AP <i>News</i></span><span>AP HOLDINGS</span></div><div class="editorial-meta">DAILY EDITION · NO. {i["number"]:03d}<span>{i["date"]} · 약 5분 읽기</span></div><h1>{esc(i["title"])}</h1><p class="editorial-intro">{esc(i["intro"])}</p><p class="source">AI 작성 및 원문 확인 · AP Holdings</p>{cover(i)}<p class="edition-note">{esc(i["edition_note"])}</p>{stories}<section class="editorial-closing"><p class="eyebrow">THE AP PERSPECTIVE</p><h2>AP의 시선</h2><p>{esc(i["takeaway"])}</p></section><p class="editorial-links"><a href="{b.pdf_path(i)}">브랜드 PDF 다운로드 ↓</a> · <a href="/ko/news/daily/">지난 호 보기 ↗</a></p></div>'
    return b.shell(i['title'],i['intro'],b.page_path(i),body,i['status']=='draft').replace('20261011-editorial','20261028-motion').replace('newsletter.js?v=20261009','newsletter.js?v=20261028-motion')

def email(i,b):
    rows=''.join(f'<tr><td style="padding:36px 28px;border-bottom:1px solid #ddd5c7"><p style="font-size:11px;letter-spacing:1px;color:#9b7950">{n:02d} / {esc(s.get("category","AI NEWS"))}</p><h2 style="font-size:23px;line-height:1.55;font-weight:500">{esc(s["title"])}</h2><p style="font-size:11px;color:#657083">{esc(s["source"])} · 발표 {esc(s["published"])}</p><p style="font-size:17px;line-height:1.8;color:#42655f">{esc(s["summary"])}</p>{b.figure(s,True)}<p style="font-size:15px;line-height:1.95">{esc(s["fact"])}</p><p style="font-size:14px;line-height:1.9;color:#526075"><b>AP의 관점</b><br>{esc(s["insight"])}</p><a style="font-size:13px;color:#9b7950" href="{esc(s["url"])}">공식 원문 ↗</a></td></tr>' for n,s in enumerate(i['stories'],1))
    return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f7f4ed;color:#172338;font-family:Arial,'Apple SD Gothic Neo',sans-serif"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:600px;margin:auto;background:#fff"><tr><td style="padding:18px;text-align:center;font-size:11px"><a href="{ORIGIN}{b.page_path(i)}" style="color:#526075">웹에서 읽기</a></td></tr><tr><td style="background:#172338;padding:24px 28px;color:#f7f4ed"><table role="presentation" width="100%"><tr><td style="font:36px Georgia,serif">AP <i>News</i></td><td align="right"><img src="{ORIGIN}/img/ap_mark.png" width="44" alt="AP"><br><span style="font-size:10px;letter-spacing:1px">AP HOLDINGS</span></td></tr></table></td></tr><tr><td style="padding:30px 28px 20px"><p style="font-size:11px;color:#9b7950;letter-spacing:1px">NO. {i['number']:03d} · {i['date']} · 약 5분 읽기</p><h1 style="font-size:30px;line-height:1.5;font-weight:500">{esc(i['title'])}</h1><p style="font-size:17px;line-height:1.9;color:#526075">{esc(i['intro'])}</p><p style="font-size:11px;color:#657083">AI 작성 및 원문 확인 · AP Holdings</p></td></tr><tr><td>{cover(i,True)}</td></tr>{rows}<tr><td style="padding:36px 28px;background:#f2f5f1"><p style="font-size:11px;color:#9b7950;letter-spacing:1px">THE AP PERSPECTIVE</p><h2 style="font-size:24px;font-weight:500">AP의 시선</h2><p style="line-height:1.9">{esc(i['takeaway'])}</p></td></tr><tr><td style="padding:30px 28px;font-size:12px;color:#657083;line-height:1.9"><a href="{ORIGIN}{b.pdf_path(i)}">브랜드 PDF 다운로드 ↓</a><p>{esc(i['edition_note'])}</p>AP Holdings · alfred.park@apholdings.kr<br><a href="{{{{unsubscribe_url}}}}">구독 해지</a></td></tr></table></body></html>'''
